```python
import sys,subprocess,os,json,yaml
release,namespace,snapshot=sys.argv[1:4]
out=subprocess.run([os.environ.get("OPSF_HELM_BIN","helm"),"template",release,".","--namespace",namespace],capture_output=True,text=True,encoding="utf8",check=True)
desired=[d for d in yaml.safe_load_all(out.stdout) if d]
existing=json.load(open(snapshot,encoding="utf8"))["items"]
def identity(obj):
 m=obj["metadata"];return (obj["apiVersion"],obj["kind"],m.get("namespace",namespace),m["name"])
index={}
for obj in existing:
 key=identity(obj)
 if key in index:raise ValueError("duplicate snapshot resource")
 index[key]=obj
result={"create":[],"owned":[],"conflicts":[]}
for obj in desired:
 key=identity(obj);record=dict(zip(("apiVersion","kind","namespace","name"),key))
 if key not in index:result["create"].append(record);continue
 meta=index[key]["metadata"];labels=meta.get("labels",{});annotations=meta.get("annotations",{})
 if labels.get("app.kubernetes.io/managed-by")=="Helm" and annotations.get("meta.helm.sh/release-name")==release and annotations.get("meta.helm.sh/release-namespace")==namespace:
  result["owned"].append(record)
 else:result["conflicts"].append(record)
for values in result.values():values.sort(key=lambda x:(x["apiVersion"],x["kind"],x["namespace"],x["name"]))
print(json.dumps(result,sort_keys=True))
sys.exit(1 if result["conflicts"] else 0)
```

实现 ownership_preflight.py RELEASE NAMESPACE SNAPSHOT，真实渲染当前Chart并与只读快照items比较。按apiVersion/kind/namespace/name识别资源：不存在归create；存在且managed-by=Helm、release-name和release-namespace三项精确匹配归owned；其余归conflicts，禁止自动改标签、删除或接管。输出三数组完整身份，存在冲突退出1，无冲突退出0；重复快照身份必须拒绝。命名空间不同的同名资源不能误判。固定fixtures/snapshot.json供练习为空快照，可信验收追加独立冲突样例；不连接API，因此只能描述所提供快照时点。

